import{_ as r,o as t,c as a,a2 as s}from"./chunks/framework.BDCokyix.js";const h=JSON.parse('{"title":"Infrastructure Services (Relay + Rendezvous)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/infra-services.md","filePath":"architecture/infra-services.md","lastUpdated":1780254295000}'),o={name:"architecture/infra-services.md"};function i(n,e,c,l,d,u){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="infrastructure-services-relay-rendezvous" tabindex="-1">Infrastructure Services (Relay + Rendezvous) <a class="header-anchor" href="#infrastructure-services-relay-rendezvous" aria-label="Permalink to &quot;Infrastructure Services (Relay + Rendezvous)&quot;">​</a></h1><p>Soma uses two lightweight libp2p infrastructure services to improve discovery and connectivity.</p><h2 id="relay-somad-relay" tabindex="-1">Relay (<code>somad relay</code>) <a class="header-anchor" href="#relay-somad-relay" aria-label="Permalink to &quot;Relay (`somad relay`)&quot;">​</a></h2><p>The relay subcommand runs the libp2p <strong>Circuit Relay v2</strong> server behaviour. Peers that cannot establish direct connections can reserve slots on the relay and route encrypted libp2p traffic through it.</p><h2 id="rendezvous-somad-rendezvous" tabindex="-1">Rendezvous (<code>somad rendezvous</code>) <a class="header-anchor" href="#rendezvous-somad-rendezvous" aria-label="Permalink to &quot;Rendezvous (`somad rendezvous`)&quot;">​</a></h2><p>The rendezvous subcommand runs the libp2p <strong>Rendezvous server</strong> behaviour. Peers register under namespaces and query for other registered peers to bootstrap connectivity.</p><p>For how peers consume relay/rendezvous (and the relevant CLI flags), see <code>docs/src/architecture/peer-connectivity.md</code>.</p><h2 id="identity-persistence" tabindex="-1">Identity Persistence <a class="header-anchor" href="#identity-persistence" aria-label="Permalink to &quot;Identity Persistence&quot;">​</a></h2><p>Both services persist a libp2p keypair so their Peer ID remains stable across restarts.</p><ul><li>Env var: <code>SOMA_DATA_DIR</code></li><li>Defaults: <ul><li>Relay: <code>./data/relay/identity.key</code></li><li>Rendezvous: <code>./data/rendezvous/identity.key</code></li></ul></li></ul><h2 id="transports" tabindex="-1">Transports <a class="header-anchor" href="#transports" aria-label="Permalink to &quot;Transports&quot;">​</a></h2><p>The services listen on multiple transports simultaneously:</p><ul><li><strong>TCP</strong>: baseline compatibility</li><li><strong>QUIC (UDP)</strong>: performance and often better NAT behavior (but UDP may be blocked)</li><li><strong>WebSocket (WS)</strong>: helpful for restrictive networks and web-like environments</li></ul><p>The exact listen addrs are currently configured in the crate defaults.</p><h2 id="soma-net-swarm-builder" tabindex="-1"><code>soma-net</code> Swarm Builder <a class="header-anchor" href="#soma-net-swarm-builder" aria-label="Permalink to &quot;`soma-net` Swarm Builder&quot;">​</a></h2><p>Soma centralizes libp2p transport wiring in <code>soma-net</code>. libp2p’s <code>SwarmBuilder</code> uses a typestate API; to compose multiple transports, the call order matters:</p><p><code>TCP -&gt; QUIC -&gt; DNS -&gt; WebSocket -&gt; Behaviour</code></p><p>If the swarm is built without QUIC support, attempting to <code>listen_on(&quot;/udp/.../quic-v1&quot;)</code> will fail with <code>MultiaddrNotSupported</code>.</p><h2 id="health-metrics" tabindex="-1">Health + Metrics <a class="header-anchor" href="#health-metrics" aria-label="Permalink to &quot;Health + Metrics&quot;">​</a></h2><p>Both services expose an HTTP server (Axum) strictly for:</p><ul><li><code>GET /healthz</code></li><li><code>GET /metrics</code> (Prometheus text)</li></ul><p>Service-specific counters track relay reservations/circuits and rendezvous registrations/discovers.</p>',22)])])}const m=r(o,[["render",i]]);export{h as __pageData,m as default};
